#!/usr/bin/env bash
# Tests for coverage-floor.sh's check and ratchet. Run by linux-ci-scripts.yml,
# or locally (it needs bash, awk and git, and leaves nothing behind):
#
#   bash .github/workflows/test_workflow_scripts/coverage-floor.tests.sh
#
# Each case runs the script in a module of its own (example.com/m, with
# a.go, b.go and gen.go, gen.go carrying Go's generated-code header), with a
# stub `go` first on PATH: its `go tool covdata textfmt -i=DIR -o=FILE` copies
# DIR/profile.txt, written by the case, to FILE. So the cases check how the
# script reads a profile, sums it and compares the sum with the floor; that
# the real covdata tool still writes this profile format is shown by the
# first run of the jobs that call the script.
#
# check: a run above its floor passes and prints its headroom; one below the
# floor less its tolerance fails and names the layer, the percentage and the
# floor; one exactly at the floor less its tolerance passes. A generated
# file's statements leave the percentage as it was, and a block that two
# binaries' data both hold counts once, covered when either covered it. A
# layer the floor file lacks fails with a line naming it.
#
# ratchet: a floor raised since the base passes, one lowered or removed fails
# and is named, a tolerance raised with the floor unchanged fails, a floor and
# tolerance raised by the same amount pass, a floor file the base does not
# have passes, and a base that is not a commit here fails.
set -u
here=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
script="$here/coverage-floor.sh"
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
fails=0

mkdir -p "$tmp/bin"
cat >"$tmp/bin/go" <<'EOF'
#!/usr/bin/env bash
# go tool covdata textfmt -i=DIR -o=FILE: copies DIR/profile.txt to FILE.
for a in "$@"; do
    case $a in -i=*) in=${a#-i=} ;; -o=*) out=${a#-o=} ;; esac
done
cp "$in/profile.txt" "$out"
EOF
chmod +x "$tmp/bin/go"

# module DIR: a module of three files under DIR, gen.go generated.
module() {
    mkdir -p "$1/.github"
    echo 'module example.com/m' >"$1/go.mod"
    printf 'package m\n' >"$1/a.go"
    printf 'package m\n' >"$1/b.go"
    printf '// Code generated by bpf2go; DO NOT EDIT.\n\npackage m\n' >"$1/gen.go"
}

# floors FILE KEY=VALUE...: writes a floor file of those keys.
floors() {
    local f=$1 kv
    shift
    : >"$f"
    for kv in "$@"; do echo "${kv%%=*}: ${kv#*=}" >>"$f"; done
}

# expect NAME WANT_RC WANT_TEXT RC OUT: the case passes when RC is WANT_RC
# (0, or 1 for any failure) and OUT holds WANT_TEXT.
expect() {
    local name=$1 want_rc=$2 want=$3 rc=$4 out=$5
    [ "$rc" -eq 0 ] || rc=1
    if [ "$rc" -ne "$want_rc" ] || [[ $out != *"$want"* ]]; then
        echo "FAIL $name: returned $rc, want $want_rc"
        echo "     printed: $out"
        echo "     want it to contain: $want"
        fails=$((fails + 1))
    else
        echo "ok   $name (rc $rc): $want"
    fi
}

# check_case NAME WANT_RC WANT_TEXT LAYER FLOORS PROFILE_LINES: runs
# `check LAYER` against a profile of PROFILE_LINES (after its mode line)
# and a floor file of FLOORS (KEY=VALUE, space-separated).
check_case() {
    local name=$1 want_rc=$2 want=$3 layer=$4 floor_spec=$5 lines=$6 d out rc
    d="$tmp/$name"
    module "$d"
    # shellcheck disable=SC2086 # the floor spec is a list of words
    floors "$d/.github/coverage-floor.yaml" $floor_spec
    mkdir -p "$d/covdata"
    printf 'mode: set\n%s\n' "$lines" >"$d/covdata/profile.txt"
    out=$(cd "$d" && PATH="$tmp/bin:$PATH" bash "$script" check "$layer" "$d/covdata" 2>&1)
    rc=$?
    expect "$name" "$want_rc" "$want" "$rc" "$out"
}

# 614 of 1000 statements: 61.40%.
p614='example.com/m/a.go:1.1,2.1 614 1
example.com/m/b.go:1.1,2.1 386 0'
check_case above-floor 0 'unit coverage 61.40%: floor 61.0, tolerance 0.2, headroom 0.40' \
    unit 'unit=61.0 unit_tolerance=0.2' "$p614"

p607='example.com/m/a.go:1.1,2.1 607 1
example.com/m/b.go:1.1,2.1 393 0'
check_case below-floor 1 'unit coverage 60.70% is below its floor 61.0 less its tolerance 0.2' \
    unit 'unit=61.0 unit_tolerance=0.2' "$p607"

p608='example.com/m/a.go:1.1,2.1 608 1
example.com/m/b.go:1.1,2.1 392 0'
check_case at-floor-less-tolerance 0 'unit coverage 60.80%: floor 61.0, tolerance 0.2, headroom -0.20' \
    unit 'unit=61.0 unit_tolerance=0.2' "$p608"

check_case generated-left-out 0 'merged coverage 61.40%' \
    merged 'merged=55.0 merged_tolerance=1.0' "$p614
example.com/m/gen.go:1.1,9.1 500 0"

# a.go's first block is in both binaries' data, covered in one: 614 covered
# of 1000, not 614 of 1614 nor 1228 of 1614.
check_case block-counted-once 0 'unit coverage 61.40%' \
    unit 'unit=61.0 unit_tolerance=0.2' "example.com/m/a.go:1.1,2.1 614 0
$p614"

check_case missing-layer 1 "has no number for 'merged' and 'merged_tolerance'" \
    merged 'unit=61.0 unit_tolerance=0.2' "$p614"

# ratchet_case NAME WANT_RC WANT_TEXT BASE_FLOORS HERE_FLOORS [BASE_REF]:
# commits a floor file of BASE_FLOORS (none when empty), writes HERE_FLOORS
# over it, and runs `ratchet BASE_REF` (HEAD unless given).
ratchet_case() {
    local name=$1 want_rc=$2 want=$3 base_spec=$4 here_spec=$5 ref=${6:-HEAD} d out rc
    d="$tmp/$name"
    module "$d"
    git -C "$d" init -q
    if [ -n "$base_spec" ]; then
        # shellcheck disable=SC2086 # the floor spec is a list of words
        floors "$d/.github/coverage-floor.yaml" $base_spec
        git -C "$d" add .github/coverage-floor.yaml
    fi
    git -C "$d" -c user.name=t -c user.email=t@example.com commit -q --allow-empty -m base
    # shellcheck disable=SC2086 # the floor spec is a list of words
    floors "$d/.github/coverage-floor.yaml" $here_spec
    out=$(cd "$d" && bash "$script" ratchet "$ref" 2>&1)
    rc=$?
    expect "$name" "$want_rc" "$want" "$rc" "$out"
}

ratchet_case floor-raised 0 "'unit' floor 61.0 at HEAD, 61.5 here: ok" \
    'unit=61.0 unit_tolerance=0.2 merged=55.0 merged_tolerance=1.0' \
    'unit=61.5 unit_tolerance=0.2 merged=55.0 merged_tolerance=1.0'

ratchet_case floor-lowered 1 "the 'merged' floor was 55.0 at HEAD and is 54.9 here; a floor can only go up" \
    'unit=61.0 unit_tolerance=0.2 merged=55.0 merged_tolerance=1.0' \
    'unit=61.0 unit_tolerance=0.2 merged=54.9 merged_tolerance=1.0'

ratchet_case floor-removed 1 "the 'merged' floor was 55.0 at HEAD and is gone or not a number here" \
    'unit=61.0 unit_tolerance=0.2 merged=55.0 merged_tolerance=1.0' \
    'unit=61.0 unit_tolerance=0.2'

# A tolerance as large as its floor would pass a run at 0%.
ratchet_case tolerance-raised 1 "the 'unit' floor less its tolerance was 60.80 at HEAD and is 0.00 here" \
    'unit=61.0 unit_tolerance=0.2 merged=55.0 merged_tolerance=1.0' \
    'unit=61.0 unit_tolerance=61.0 merged=55.0 merged_tolerance=1.0'

ratchet_case floor-and-tolerance-raised 0 "'unit' floor 61.0 at HEAD, 62.0 here: ok" \
    'unit=61.0 unit_tolerance=0.2 merged=55.0 merged_tolerance=1.0' \
    'unit=62.0 unit_tolerance=1.2 merged=55.0 merged_tolerance=1.0'

ratchet_case new-floor-file 0 'is new since HEAD: nothing to compare' \
    '' 'unit=61.0 unit_tolerance=0.2'

ratchet_case base-not-a-commit 1 'origin/main is not a commit here' \
    'unit=61.0 unit_tolerance=0.2' 'unit=61.0 unit_tolerance=0.2' origin/main

if [ "$fails" -gt 0 ]; then
    echo "$fails case(s) failed"
    exit 1
fi
echo "all cases passed"
